package com.jotalbot.madworld.data

import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URI
import java.util.UUID

class MadWorldApi(private val baseUrl: String) {
    fun createSession(handle: String): SessionState { val url=URI.create("${baseUrl.trimEnd('/')}/api/v1/sessions").toURL(); val c=(url.openConnection() as HttpURLConnection).apply{requestMethod="POST";doOutput=true;connectTimeout=10_000;readTimeout=10_000;setRequestProperty("Content-Type","application/json");setRequestProperty("Accept","application/json")}; try{c.outputStream.use{it.write(JSONObject().put("handle",handle).toString().toByteArray())};if(c.responseCode !in 200..299)throw ApiException("session request failed: HTTP ${c.responseCode}");val r=JSONObject(c.inputStream.bufferedReader().use{it.readText()});return SessionState(UUID.fromString(r.getString("player_id")),r.getString("handle"),r.getString("token"),r.getString("expires_at"))}finally{c.disconnect()} }
    fun fetchPlayerState(playerId:UUID,token:String?=null):PlayerState{val c=connection("/api/v1/players/$playerId/state","GET",token);try{if(c.responseCode !in 200..299)throw ApiException("state request failed: HTTP ${c.responseCode}");return parseState(c.inputStream.bufferedReader().use{it.readText()})}finally{c.disconnect()}}
    fun fetchSettlement(playerId:UUID,token:String):SettlementState{val c=connection("/api/v1/settlement","GET",token);try{if(c.responseCode !in 200..299)throw ApiException("settlement request failed: HTTP ${c.responseCode}");val r=JSONObject(c.inputStream.bufferedReader().use{it.readText()});if(UUID.fromString(r.getString("owner_id"))!=playerId)throw ApiException("settlement owner mismatch");val m=r.getJSONObject("modules");val cap=r.getJSONObject("capabilities");return SettlementState(UUID.fromString(r.getString("id")),playerId,r.getString("region"),r.getInt("level"),buildMap{m.keys().forEach{put(it,m.getInt(it))}},buildMap{cap.keys().forEach{put(it,cap.getBoolean(it))}},r.getInt("version"))}finally{c.disconnect()}}
    fun fetchEconomyOverview(playerId:UUID,token:String):EconomyOverviewState{val c=connection("/api/v1/economy/overview","GET",token);try{if(c.responseCode !in 200..299)throw ApiException("economy overview request failed: HTTP ${c.responseCode}");return parseEconomyOverview(c.inputStream.bufferedReader().use{it.readText()},playerId)}finally{c.disconnect()}}
    fun fetchSocialCapabilities(token:String):List<String>{val c=connection("/api/v1/social/capabilities","GET",token);try{if(c.responseCode !in 200..299)throw ApiException("social capabilities failed: HTTP ${c.responseCode}");val a=JSONObject(c.inputStream.bufferedReader().use{it.readText()}).getJSONArray("systems");return buildList{for(i in 0 until a.length())add(a.getString(i))}}finally{c.disconnect()}}
    fun fetchCorporationOverview(corporationId:UUID,token:String):CorporationState{val c=connection("/api/v1/social/overview/$corporationId","GET",token);try{if(c.responseCode !in 200..299)throw ApiException("corporation overview failed: HTTP ${c.responseCode}");val r=JSONObject(c.inputStream.bufferedReader().use{it.readText()});val x=r.getJSONObject("corporation");return CorporationState(UUID.fromString(x.getString("id")),x.getString("code"),x.getString("name"),r.getString("viewer_role"),x.getInt("tax_bps"),r.getJSONArray("members").length())}finally{c.disconnect()}}
    fun createCorporation(code:String,name:String,taxBps:Int,token:String,idempotencyKey:String=UUID.randomUUID().toString()):UUID{val c=connection("/api/v1/social/corporations","POST",token);c.doOutput=true;c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Idempotency-Key",idempotencyKey);try{c.outputStream.use{it.write(JSONObject().put("code",code).put("name",name).put("tax_bps",taxBps).toString().toByteArray())};if(c.responseCode !in 200..299)throw ApiException("corporation creation failed: HTTP ${c.responseCode}");return UUID.fromString(JSONObject(c.inputStream.bufferedReader().use{it.readText()}).getString("corporation_id"))}finally{c.disconnect()}}
    private fun connection(path:String,method:String,token:String?):HttpURLConnection=(URI.create("${baseUrl.trimEnd('/')}$path").toURL().openConnection() as HttpURLConnection).apply{requestMethod=method;connectTimeout=10_000;readTimeout=10_000;setRequestProperty("Accept","application/json");token?.let{setRequestProperty("Authorization","Bearer $it")}}
    private fun parseEconomyOverview(json:String,playerId:UUID):EconomyOverviewState{val r=JSONObject(json);val jobs=buildList{val a=r.getJSONArray("active_jobs");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(EconomyJobState(UUID.fromString(x.getString("id")),x.getString("kind"),UUID.fromString(x.getString("recipe_id")),UUID.fromString(x.getString("settlement_id")),x.getString("state"),x.getString("completes_at")))}};val f=buildList{val a=r.getJSONArray("facilities");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(EconomyFacilityState(x.getString("code"),x.getInt("level"),x.getInt("efficiency_bps")))}};return EconomyOverviewState(UUID.fromString(r.getString("settlement_id")),r.getString("region"),r.getInt("warehouse_capacity"),r.getInt("warehouse_used"),f,jobs,r.getInt("contract_count"),r.getInt("ready_vehicles"),r.getInt("market_price_points"),r.getString("next_action"))}
    private fun parseState(json:String):PlayerState{val r=JSONObject(json);val ch=if(r.isNull("character"))null else parseCharacter(r.getJSONObject("character"));val v=buildList{val a=r.getJSONArray("vehicles");for(i in 0 until a.length())add(parseVehicle(a.getJSONObject(i)))};val w=if(r.isNull("wallet"))null else r.getJSONObject("wallet").let{WalletState(UUID.fromString(it.getString("id")),it.getLong("balance"),it.getInt("version"))};val inv=buildList{val a=r.getJSONArray("inventory");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(InventoryState(UUID.fromString(x.getString("inventory_id")),UUID.fromString(x.getString("item_definition_id")),x.getLong("quantity"),x.getInt("condition"),x.getInt("version")))}};val jobs=buildList{val a=r.getJSONArray("active_jobs");for(i in 0 until a.length()){val x=a.getJSONObject(i);add(JobState(UUID.fromString(x.getString("id")),UUID.fromString(x.getString("owner_id")),x.getString("job_type"),x.getString("started_at"),x.getString("completes_at"),x.getString("state"),x.getInt("version")))}};return PlayerState(ch,v,w,inv,jobs)}
    private fun parseCharacter(j:JSONObject)=CharacterState(UUID.fromString(j.getString("id")),UUID.fromString(j.getString("player_id")),j.getString("name"),j.getInt("level"),j.getInt("version"))
    private fun parseVehicle(j:JSONObject)=VehicleState(UUID.fromString(j.getString("id")),UUID.fromString(j.getString("owner_id")),j.getString("code"),j.getString("chassis_code"),j.getInt("durability"),j.getInt("fuel"),j.getString("state"),j.getInt("version"))
}
data class SessionState(val playerId:UUID,val handle:String,val token:String,val expiresAt:String)
class ApiException(message:String):RuntimeException(message)
